import requests, json, os, concurrent.futures

base = "/workspace/data/biomni_data/p04637"
ids = ["1TUP", "1GZH", "2AC0", "4QO1", "8A31", "9R2Q"]

def get_mapping(pdb_id):
    url = f"https://www.ebi.ac.uk/pdbe/api/mappings/uniprot/{pdb_id}"
    try:
        r = requests.get(url, timeout=90, headers={"Accept":"application/json","User-Agent":"Biomni-P04637-mapping/1.0"})
        print(f"{pdb_id}: HTTP {r.status_code}, {len(r.content)} bytes")
        if r.ok:
            with open(f"{base}/sifts_{pdb_id}.json", "w") as f:
                json.dump(r.json(), f, indent=2)
            return pdb_id, r.json()
    except Exception as e:
        print(f"{pdb_id}: FAILED {e}")
    return pdb_id, None

with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex:
    maps = dict(ex.map(get_mapping, ids))

for pdb_id, obj in maps.items():
    print(f"\n=== {pdb_id} ===")
    print(json.dumps(obj, indent=2)[:6000])

# Query RCSB GraphQL for the handful of source-discrepant entries.
query = """
query($ids:[String!]!) {
  entries(entry_ids:$ids) {
    rcsb_id
    struct { title }
    rcsb_accession_info { initial_release_date deposit_date }
    polymer_entities {
      rcsb_id
      rcsb_polymer_entity_container_identifiers {
        asym_id auth_asym_ids
        reference_sequence_identifiers { database_accession database_name }
      }
      rcsb_polymer_entity_align {
        reference_database_accession
        aligned_regions { entity_beg_seq_id ref_beg_seq_id length }
      }
      entity_poly { pdbx_seq_one_letter_code_can }
    }
  }
}
"""
ids_diff = ["2F1X", "2V5W", "6VQO", "8ZZN", "9A9W"]
r = requests.post("https://data.rcsb.org/graphql", json={"query":query,"variables":{"ids":ids_diff}}, timeout=120,
                 headers={"Content-Type":"application/json","User-Agent":"Biomni-P04637-mapping/1.0"})
print("\nRCSB GraphQL discrepant entries: HTTP", r.status_code)
if r.ok:
    obj = r.json()
    with open(f"{base}/rcsb_discrepant_graphql.json", "w") as f:
        json.dump(obj, f, indent=2)
    for e in obj.get("data",{}).get("entries",[]):
        print(f"\n{e.get('rcsb_id')} | release {e.get('rcsb_accession_info',{}).get('initial_release_date')} | {e.get('struct',{}).get('title')}")
        for ent in e.get("polymer_entities",[]):
            ids_obj = ent.get("rcsb_polymer_entity_container_identifiers",{})
            refs = ids_obj.get("reference_sequence_identifiers") or []
            aln = ent.get("rcsb_polymer_entity_align") or []
            seq = ent.get("entity_poly",{}).get("pdbx_seq_one_letter_code_can")
            if refs or any((a.get("reference_database_accession") or "").upper()=="P04637" for a in aln):
                print(" entity", ent.get("rcsb_id"), "ids", ids_obj, "refs", refs, "align", aln, "seqlen", len(seq or ""))
else:
    print(r.text[:2000])
